/* Relative swept hull geometry, in canonical world coordinates before camera projection. */
static int swept_ellipse(float x,float y,float xx,float yy,float rx,float ry){x/=rx;y/=ry;xx/=rx;yy/=ry;float dx=xx-x,dy=yy-y,d=dx*dx+dy*dy,t=d>0?fmaxf(0,fminf(1,-(x*dx+y*dy)/d)):0;x+=dx*t;y+=dy*t;return x*x+y*y<=1;}
static int hostile_hull_contact(const Obj*b,int bx,int by){float radius=b->type==1?3:2;return swept_ellipse((bx-ex.damagePrevX)/(float)Q,(by-ex.damagePrevY)/(float)Q,(b->x-g.px)/(float)Q,(b->y-player_y)/(float)Q,player_hull_rx()+radius,player_hull_ry()+radius);}
static int enemy_body_contact(const Obj*o,int ox,int oy){int side=pc_enemy_side_body77(o,ox,oy);if(side>=0)return side;float rx=o->type==26?4:o->type==4?32+o->power/24.0f:o->type>=10&&o->type<14?10:14,ry=o->type==26?5:o->type==4?26+o->power/32.0f:o->type>=10&&o->type<14?11:15;if(floor_enemy(o)&&o->floorMounted){float a=o->heading/916.732472f,c=cosf(a),s=sinf(a),w=organic_context()?12:o->type==23?15.33f:11.76f,h=organic_context()?14:o->type==23?5.57f:10.2f;rx=sqrtf(w*w*c*c+h*h*s*s);ry=sqrtf(w*w*s*s+h*h*c*c);}return swept_ellipse((ox-ex.damagePrevX)/(float)Q,(oy-ex.damagePrevY)/(float)Q,(o->x-g.px)/(float)Q,(o->y-player_y)/(float)Q,rx+player_hull_rx(),ry+player_hull_ry());}
static void player_respawn_safe(void){g.px=160*Q;player_y=(ex.giant.active?play_max_y()-16:230)*Q;if(tunnel_visible(player_y/Q))g.px=tunnel_lane(player_y/Q,0)*Q;terrain_respawn_clear();ex.damagePrevX=g.px;ex.damagePrevY=player_y;for(int i=0;i<MAXB;i++)if(g.bullets[i].on&&absn(g.bullets[i].x-g.px)<40*Q&&absn(g.bullets[i].y-player_y)<40*Q)g.bullets[i].on=0;}

static int enemy_shot_contact(const Obj*o,const Obj*s){int side=pc_enemy_side_hit77(o,s->x,s->y,2);if(side>=0)return side;if(floor_enemy(o)&&o->floorMounted)return floor_shot_hit(o,s->x,s->y);return absn((s->x-o->x)/Q)<(o->type==4?33+o->power/24:o->type>=14?15:o->type>=10?10:14)&&absn((s->y-o->y)/Q)<(o->type==4?26:o->type>=10?10:15);}
